-- 0009_catalogo_marcas.sql — catálogo do sistema (dono nulo): maltes das marcas mais vendidas no Brasil e lúpulos
-- em lupulina concentrada / cultivados no Brasil. 23/11/2026.
--
-- Por quê: o catálogo da 0004 tinha maltes genéricos (beer-analytics) e só a The Swaen como marca. Levantamento em
-- lojas brasileiras (Lamas, Piquiri, Empório do Lúpulo, WE, Estação; nov/2026): Weyermann, Castle (Château) e Agrária
-- em todas; Viking, Crisp e Dingemans na maioria; Uma Malta (que também traz a Pauls Malt) forte em algumas.
-- Entram: Weyermann, Agrária, Dingemans, BestMalz, Viking Malt, Uma Malta e Pauls Malt (fichas do site da Uma Malta,
-- distribuidora oficial). FORA por ora: Castle/Château e Crisp (os sites recusam acesso automatizado) e Yakima Chief
-- Cryo/LUPOMAX (sem números oficiais acessíveis); lúpulo Mantiqueira (análise não conferida).
-- Lúpulos: Lupulin Pellets da Hopsteiner (forma CRIO) e Cascade/Comet cultivados no Brasil (Embrapa, manual de 2022).
-- De onde vêm os números: SÓ fichas técnicas oficiais dos fabricantes, abertas e lidas uma a uma (URL em extras.url).
-- Nada de texto descritivo dos fabricantes (direitos autorais): notas curtas próprias, em português.
-- Regras: cor = meio da faixa publicada em EBC, gravada em SRM (EBC ÷ 1,97; a faixa fica nas notas e em extras.cor_ebc);
-- rendimento = extrato base seca (moagem fina); umidade = máxima publicada. Sem extrato/umidade publicados: valor
-- típico do grupo, avisado nas notas. Lúpulos: alfa/beta/óleo = meio da faixa oficial; faixa nas notas.
-- Nomes levam a marca (a receita copia só o nome). Item cujo nome já existe no catálogo do sistema não entra de novo.
-- Contagem esperada: 173 maltes e 22 lúpulos.

insert into public.fermentaveis
  (nome, tipo, grupo, produtor, origem, rendimento_pct, cor_srm, umidade_pct, fermentavel_pct, precisa_mostura,
   max_lote_pct, notas, extras)
select v.nome, 'GRAO', v.grupo, v.produtor, v.origem, v.rendimento::numeric, v.srm::numeric, v.umidade::numeric, 100,
       v.mostura, v.max_pct::numeric,
       concat_ws(' ', nullif(v.nota, ''), 'Cor ' || v.cor_ebc || ' EBC.'),
       jsonb_build_object('fonte', 'Ficha técnica oficial (' || v.produtor || '), consultada em 23/11/2026',
                          'url', v.url, 'cor_ebc', v.cor_ebc, 'pasta', v.produtor)
from (values
  ('Weyermann Extra Pale Premium Pilsner Malt', 'BASE', 'Weyermann', 'Germany', 80.5, 1.4, 5, true, 100, '2–3,5', 'Base extra clara; para lagers bem claras.', 'https://www.weyermann.de/wp-content/uploads/2019/11/Weyermann%C2%AE-Extra-Pale-Premium-Pilsner-Malt_Specification.pdf'),
